import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Action Pipeline Performance","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/action-performance.md","filePath":"en/modules/corelib/action-performance.md","lastUpdated":0}`),a={name:`en/modules/corelib/action-performance.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="action-pipeline-performance" tabindex="-1">Action Pipeline Performance <a class="header-anchor" href="#action-pipeline-performance" aria-label="Permalink to “Action Pipeline Performance”">​</a></h1><p>This page is the performance stance of the Emaki action pipeline: statically provable architectural advantages, a reproducible benchmark method, and the results table. <strong>This environment has no Paper/Folia server, so every quantified cell is marked &quot;not run&quot; with a closing condition</strong> — architecture claims are backed by source code, but numbers must come from a real server before they may be cited externally</p><h2 id="architectural-advantages-source-verifiable" tabindex="-1">Architectural advantages (source-verifiable) <a class="header-anchor" href="#architectural-advantages-source-verifiable" aria-label="Permalink to “Architectural advantages (source-verifiable)”">​</a></h2><h3 id="_1-compiled-once-zero-parsing-at-runtime" tabindex="-1">1. Compiled once, zero parsing at runtime <a class="header-anchor" href="#_1-compiled-once-zero-parsing-at-runtime" aria-label="Permalink to “1. Compiled once, zero parsing at runtime”">​</a></h3><p>A pipeline is compiled exactly once at config load through <code>PipelineParser</code> + <code>StaticValidator</code> into a <code>CompiledPipeline</code> (AST + type-checked arguments). At runtime <code>ActionInterpreter</code> executes that structure directly:</p><ul><li>no re-tokenization, no argument type checks, no unknown-stage lookups;</li><li>argument rendering only runs <code>render</code> for values containing placeholders; pure literals are skipped;</li><li>compile failures are reported in full at load time (48+ rules), so there is no &quot;found out at runtime&quot; path for a wrong stage name</li></ul><h3 id="_2-gate-short-circuiting-and-domain-grouping" tabindex="-1">2. Gate short-circuiting and domain grouping <a class="header-anchor" href="#_2-gate-short-circuiting-and-domain-grouping" aria-label="Permalink to “2. Gate short-circuiting and domain grouping”">​</a></h3><ul><li><strong>Gate short-circuit</strong>: a source returning <code>Empty</code> or a gate returning <code>Halted</code> enters a terminal state (<code>stopped</code>) immediately; all later stages are skipped with no cross-domain dispatch</li><li><strong>Same-domain batching</strong>: <code>StageGroup</code> folds consecutive same-domain stages into one dispatch (<code>foldable</code> stages attach to the previous group), reducing Paper/Folia thread hops — e.g. two <code>CONTEXT_ENTITY</code> stages (&quot;edit inventory&quot; + &quot;set XP&quot;) cause a single owner-thread transfer</li><li><strong>Five-domain classification</strong>: <code>SERVER_GLOBAL</code> / <code>CONTEXT_ENTITY</code> / <code>LOCATION_REGION</code> / <code>ASYNC_COMPUTE</code> / <code>UNDECLARED</code> are mandatory at registration (<code>StageRegistry.checkDomain</code>); <code>StageDispatcher</code> routes by domain at runtime. <strong>Competitors generally have no domain classification</strong>, which is Emaki&#39;s structural difference on Folia</li></ul><h3 id="_3-zero-allocation-observation-on-hot-paths" tabindex="-1">3. Zero-allocation observation on hot paths <a class="header-anchor" href="#_3-zero-allocation-observation-on-hot-paths" aria-label="Permalink to “3. Zero-allocation observation on hot paths”">​</a></h3><p>The default <code>StepReporter</code> is <code>NOOP</code> (empty interface methods), so in non-debug runs every observation point is an empty call; <code>ActionAuditLogger</code> returns early when there is no <code>DebugLogger</code>. The observation layer adds no allocation or branching to production hot paths</p><h3 id="_4-elimination-before-execution" tabindex="-1">4. Elimination before execution <a class="header-anchor" href="#_4-elimination-before-execution" aria-label="Permalink to “4. Elimination before execution”">​</a></h3><p>Every gate&#39;s in/out counts are reported on <code>StepReporter.gate</code> (rendered as a funnel in dry-run/debug mode); semantically &quot;filter first, act later&quot; — <code>filter</code>/<code>where</code> eliminate unqualified targets before any action runs, avoiding cross-domain dispatches for invalid targets</p><h2 id="benchmark-method-reproducible" tabindex="-1">Benchmark method (reproducible) <a class="header-anchor" href="#benchmark-method-reproducible" aria-label="Permalink to “Benchmark method (reproducible)”">​</a></h2><p>Follow the sampling discipline in <code>.spigot-dev/guides/performance-baseline.md</code>: only same-scenario, same-duration, same-scale runs are comparable. Three required scenarios:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Measures</th><th>Trigger</th><th>Budget</th></tr></thead><tbody><tr><td>Pipeline throughput</td><td>Completed pipeline runs per second</td><td>Run a fixed short pipeline (e.g. <code>self | damage amount=1</code>) in <code>execute</code> mode for a 120s spark sample</td><td>Fill after a real-server baseline</td></tr><tr><td>P95 latency</td><td>End-to-end latency of one pipeline</td><td>Same as above, with method-level sampling of <code>ActionInterpreter.walk</code></td><td>Fill after a real-server baseline</td></tr><tr><td>Gate short-circuit benefit</td><td>Elapsed time of <code>Halted</code>/<code>Empty</code> path vs all-pass path</td><td>Compare <code>filter &#39;health_percent&lt;=0&#39;</code> (always eliminates everything) against <code>filter &#39;health_percent&lt;=100&#39;</code> (always passes)</td><td>Short-circuit path should be significantly cheaper</td></tr></tbody></table><p>Observation commands:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/spark profiler start --timeout 120</span></span>
<span class="line"><span># run the fixed scenario...</span></span>
<span class="line"><span>/spark profiler stop --save-to-file</span></span></code></pre></div><p>To measure grouping benefit, compare <code>StageDispatcher.dispatch</code> call count against dispatched stage count in the spark method profile — with batching active that ratio should be clearly below 1</p><h2 id="quantified-results" tabindex="-1">Quantified results <a class="header-anchor" href="#quantified-results" aria-label="Permalink to “Quantified results”">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th><th>Collected</th><th>Status</th></tr></thead><tbody><tr><td>Pipeline throughput (runs/s)</td><td>—</td><td>—</td><td><strong>not run</strong></td></tr><tr><td>P95 end-to-end latency</td><td>—</td><td>—</td><td><strong>not run</strong></td></tr><tr><td>Gate short-circuit benefit (short-circuit vs all-pass)</td><td>—</td><td>—</td><td><strong>not run</strong></td></tr><tr><td>Dispatches per stage after batching</td><td>—</td><td>—</td><td><strong>not run</strong></td></tr></tbody></table><p><strong>Closing condition</strong>: on a Paper 1.21.8 server, run one spark sample per scenario above, fill the numbers back into this table with a collection date. Until then no quantified cell may be filled with estimated values</p><h2 id="comparison-stance-against-competitors" tabindex="-1">Comparison stance against competitors <a class="header-anchor" href="#comparison-stance-against-competitors" aria-label="Permalink to “Comparison stance against competitors”">​</a></h2><ul><li><strong>Statically citable</strong> (source-level facts): five-domain thread grouping with mandatory Folia domain declarations (MythicMobs/Skript have no such mechanism); 48+ compile-time diagnostics (MythicMobs relies on runtime errors + guessing from the Wiki)</li><li><strong>Not citable</strong>: any throughput, latency, or TPS number. Competitor figures are marketing claims too; re-check the source date before quoting them externally</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};